B.c90=new A.c5([B.lO,B.bSN,B.lP,B.b3u,B.k2,B.bSE,B.mS,B.c1A,B.mT,B.bWD],t.lZ)
B.bTL=s(["\u0645\u0646\u062a\u0635\u0641 \u0627\u0644\u064a\u0648\u0645: \u0627\u0633\u062a\u0631\u0627\u062d\u0629\u064c \u0642\u0635\u064a\u0631\u0629 \u062b\u0645 \u064a\u064f\u0633\u062a\u0623\u0646\u0641 \u0627\u0644\u0639\u0645\u0644.","\u062e\u062f\u0645\u0629 \u0627\u0644\u0642\u0631\u0622\u0646 \u0639\u0628\u0627\u062f\u0629\u064c \u0641\u064a \u0643\u0644 \u0633\u0627\u0639\u0629\u060c \u062a\u0642\u0628\u0651\u0644 \u0627\u0644\u0644\u0647 \u0645\u0646\u0643.","\u0646\u0635\u0641 \u0627\u0644\u0646\u0647\u0627\u0631 \u0645\u0636\u0649 \u0628\u062e\u064a\u0631\u060c \u0648\u0645\u0627 \u0628\u0642\u064a \u0623\u064a\u0633\u0631 \u0628\u0625\u0630\u0646 \u0627\u0644\u0644\u0647.","\u0646\u0638\u0631\u0629\u064c \u0642\u0635\u064a\u0631\u0629 \u0639\u0644\u0649 \u0623\u0631\u0642\u0627\u0645 \u0627\u0644\u0634\u0647\u0631 \u062a\u0643\u0641\u064a \u0644\u0645\u0639\u0631\u0641\u0629 \u0645\u0627 \u064a\u062d\u062a\u0627\u062c \u0645\u062a\u0627\u0628\u0639\u0629.","\u0643\u0644 \u062a\u064a\u0633\u064a\u0631\u064d \u0625\u062f\u0627\u0631\u064a\u0651 \u064a\u0646\u0639\u0643\u0633 \u0647\u062f\u0648\u0621\u064b\u0627 \u0641\u064a \u0627\u0644\u062d\u0644\u0642\u0627\u062a\u061b \u0628\u0627\u0631\u0643 \u0627\u0644\u0644\u0647 \u0641\u064a\u0643."],t.s)
B.bQm=s(["\u0646\u0635\u0641 \u0627\u0644\u064a\u0648\u0645 \u0645\u0636\u0649\u061b \u0645\u0627 \u0628\u0642\u064a \u0645\u0646 \u0627\u0644\u0645\u062a\u0627\u0628\u0639\u0629 \u062a\u062c\u062f\u0647 \u0623\u0633\u0641\u0644 \u0627\u0644\u0635\u0641\u062d\u0629.","\u0627\u0633\u062a\u0631\u0627\u062d\u0629\u064c \u0642\u0635\u064a\u0631\u0629 \u062a\u062c\u062f\u0651\u062f \u0627\u0644\u0647\u0645\u0651\u0629 \u0644\u0645\u0627 \u0628\u0642\u064a \u0645\u0646 \u0627\u0644\u0632\u064a\u0627\u0631\u0627\u062a.","\u0627\u0644\u0639\u0645\u0644 \u0627\u0644\u0645\u062a\u0651\u0635\u0644 \u0648\u0625\u0646 \u0642\u0644\u0651 \u0623\u062d\u0628\u0651 \u0625\u0644\u0649 \u0627\u0644\u0644\u0647\u061b \u0623\u0639\u0627\u0646\u0643 \u0627\u0644\u0644\u0647.","\u0645\u0627 \u0628\u064a\u0646 \u0627\u0644\u0632\u064a\u0627\u0631\u0627\u062a \u0648\u0642\u062a\u064c \u0645\u0646\u0627\u0633\u0628 \u0644\u0643\u062a\u0627\u0628\u0629 \u062a\u0642\u0627\u0631\u064a\u0631\u0647\u0627.","\u0645\u0644\u0627\u062d\u0638\u0629\u064c \u062a\u064f\u0643\u062a\u0628 \u0641\u064a \u0648\u0642\u062a\u0647\u0627 \u0623\u062f\u0642\u0651 \u0645\u0646 \u0645\u0644\u0627\u062d\u0638\u0629\u064d \u062a\u064f\u0633\u062a\u0639\u0627\u062f \u0645\u0646 \u0627\u0644\u0630\u0627\u0643\u0631\u0629."],t.s)
B.c1g=s(["\u0627\u0633\u062a\u0639\u062f\u0627\u062f\u064c \u0647\u0627\u062f\u0626 \u0644\u0644\u062d\u0644\u0642\u0629 \u064a\u062c\u0639\u0644\u0647\u0627 \u0623\u064a\u0633\u0631.","\u062a\u0639\u0644\u064a\u0645 \u0627\u0644\u0642\u0631\u0622\u0646 \u0645\u0646 \u062e\u064a\u0631 \u0627\u0644\u0623\u0639\u0645\u0627\u0644\u061b \u062a\u0642\u0628\u0651\u0644 \u0627\u0644\u0644\u0647 \u0645\u0646\u0643.","\u0648\u0642\u062a\u064c \u0645\u0646\u0627\u0633\u0628 \u0644\u0645\u0631\u0627\u062c\u0639\u0629 \u062e\u0637\u0629 \u0637\u0644\u0627\u0628 \u0627\u0644\u064a\u0648\u0645.","\u0646\u0638\u0631\u0629\u064c \u0639\u0644\u0649 \u0645\u0646 \u062a\u0623\u062e\u0651\u0631 \u0645\u0646 \u0627\u0644\u0637\u0644\u0627\u0628 \u0642\u0628\u0644 \u0627\u0644\u062d\u0644\u0642\u0629 \u062a\u062c\u0639\u0644\u0647\u0627 \u0623\u064a\u0633\u0631.","\u0646\u064a\u0651\u0629\u064c \u0645\u062a\u062c\u062f\u0651\u062f\u0629 \u0642\u0628\u0644 \u0627\u0644\u062d\u0644\u0642\u0629 \u062a\u0628\u0627\u0631\u0643 \u0627\u0644\u062c\u0647\u062f \u0643\u0644\u0651\u0647."],t.s)
B.c4C=s(["\u0627\u0633\u062a\u0631\u0627\u062d\u0629\u064c \u0642\u0635\u064a\u0631\u0629 \u0642\u0628\u0644 \u0645\u062c\u0627\u0644\u0633 \u0627\u0644\u064a\u0648\u0645.","\u0646\u064a\u0651\u0629\u064c \u0645\u062a\u062c\u062f\u0651\u062f\u0629 \u062a\u064f\u0628\u0627\u0631\u0643 \u0627\u0644\u0645\u062c\u0644\u0633\u061b \u0623\u0639\u0627\u0646\u0643 \u0627\u0644\u0644\u0647.","\u0646\u0635\u0641 \u0627\u0644\u064a\u0648\u0645 \u0645\u0636\u0649\u061b \u0645\u0648\u0627\u0639\u064a\u062f \u0645\u0627 \u0628\u0639\u062f\u0647 \u062a\u062c\u062f\u0647\u0627 \u0647\u0646\u0627.","\u0645\u0631\u0627\u062c\u0639\u0629\u064c \u0642\u0635\u064a\u0631\u0629 \u0644\u0645\u0648\u0636\u0639 \u0627\u0644\u0642\u0627\u0631\u0626 \u0642\u0628\u0644 \u0627\u0644\u0645\u062c\u0644\u0633 \u062a\u062e\u062a\u0635\u0631 \u0627\u0644\u0648\u0642\u062a.","\u0636\u0628\u0637 \u0627\u0644\u0645\u062c\u0644\u0633 \u064a\u0628\u062f\u0623 \u0642\u0628\u0644 \u0623\u0646 \u064a\u0628\u062f\u0623\u061b \u0623\u0639\u0627\u0646\u0643 \u0627\u0644\u0644\u0647."],t.s)
B.bsr=s(["\u0627\u0633\u062a\u0639\u062f\u0627\u062f\u064c \u0647\u0627\u062f\u0626 \u0644\u0644\u062c\u0646\u0629 \u064a\u062c\u0639\u0644\u0647\u0627 \u0623\u064a\u0633\u0631 \u0639\u0644\u064a\u0643 \u0648\u0639\u0644\u0649 \u0627\u0644\u0637\u0644\u0627\u0628.","\u0646\u064a\u0651\u0629\u064c \u0645\u062a\u062c\u062f\u0651\u062f\u0629 \u062a\u0628\u0627\u0631\u0643 \u0627\u0644\u0644\u062c\u0646\u0629\u061b \u0623\u0639\u0627\u0646\u0643 \u0627\u0644\u0644\u0647.","\u0646\u0635\u0641 \u0627\u0644\u064a\u0648\u0645 \u0645\u0636\u0649\u061b \u0645\u0648\u0627\u0639\u064a\u062f \u0645\u0627 \u0628\u0639\u062f\u0647 \u062a\u062c\u062f\u0647\u0627 \u0647\u0646\u0627.","\u0646\u0638\u0631\u0629\u064c \u0639\u0644\u0649 \u0642\u0627\u0626\u0645\u0629 \u0627\u0644\u0644\u062c\u0646\u0629 \u0642\u0628\u0644 \u0645\u0648\u0639\u062f\u0647\u0627 \u062a\u062e\u062a\u0635\u0631 \u0627\u0644\u0627\u0646\u062a\u0638\u0627\u0631.","\u0627\u0644\u0639\u062f\u0644 \u0641\u064a \u0627\u0644\u0644\u062c\u0646\u0629 \u064a\u0628\u062f\u0623 \u0645\u0646 \u0647\u062f\u0648\u0621 \u0627\u0644\u0645\u062e\u062a\u0628\u0650\u0631\u061b \u0623\u0639\u0627\u0646\u0643 \u0627\u0644\u0644\u0647."],t.s)
B.c9_=new A.c5([B.lO,B.bTL,B.lP,B.bQm,B.k2,B.c1g,B.mS,B.c4C,B.mT,B.bsr],t.lZ)
B.bV0=s(["\u0633\u0627\u0639\u0627\u062a \u0627\u0644\u062d\u0644\u0642\u0627\u062a \u0639\u0635\u0631\u064b\u0627 \u0648\u0645\u063a\u0631\u0628\u064b\u0627\u061b \u0627\u0644\u0645\u0631\u0627\u0643\u0632 \u0639\u0627\u0645\u0631\u0629\u064c \u0628\u0623\u0635\u0648\u0627\u062a \u0627\u0644\u0642\u0631\u0622\u0646.","\u0645\u0627 \u064a\u0637\u0631\u0623 \u0641\u064a \u062d\u0644\u0642\u0627\u062a \u0627\u0644\u064a\u0648\u0645 \u062a\u062c\u062f\u0647 \u0647\u0646\u0627.","\u0641\u064a \u062d\u0644\u0642\u0627\u062a \u0627\u0644\u064a\u0648\u0645 \u062a\u064f\u062a\u0644\u0649 \u0622\u064a\u0627\u062a\u064c \u0643\u062b\u064a\u0631\u0629 \u0641\u064a \u0645\u0631\u0627\u0643\u0632\u0643\u061b \u0627\u0644\u062d\u0645\u062f \u0644\u0644\u0647.","\u062d\u0644\u0642\u0629\u064c \u0639\u0627\u0645\u0631\u0629 \u0641\u064a \u0645\u0631\u0643\u0632\u064d \u0628\u0639\u064a\u062f \u062b\u0645\u0631\u0629\u064f \u0642\u0631\u0627\u0631\u064d \u0625\u062f\u0627\u0631\u064a\u0651 \u0635\u0627\u0626\u0628\u061b \u0627\u0644\u062d\u0645\u062f \u0644\u0644\u0647.","\u0623\u0635\u0648\u0627\u062a \u0627\u0644\u0637\u0644\u0627\u0628 \u0641\u064a \u062d\u0644\u0642\u0627\u062a \u0627\u0644\u064a\u0648\u0645 \u062b\u0645\u0631\u0629 \u062c\u0647\u062f\u064d \u0645\u0634\u062a\u0631\u0643\u061b \u0628\u0627\u0631\u0643 \u0627\u0644\u0644\u0647 \u0641\u064a\u0647."],t.s)
B.bDK=s(["\u0632\u064a\u0627\u0631\u0629\u064c \u0645\u064a\u062f\u0627\u0646\u064a\u0629 \u0641\u064a \u0648\u0642\u062a \u0627\u0644\u062d\u0644\u0642\u0629 \u062a\u0635\u0646\u0639 \u0641\u0631\u0642\u064b\u0627\u061b \u0648\u0641\u0651\u0642\u0643 \u0627\u0644\u0644\u0647.","\u0632\u064a\u0627\u0631\u0629\u064c \u0641\u064a \u0648\u0642\u062a \u0627\u0644\u062d\u0644\u0642\u0629 \u062a\u064f\u063a\u0646\u064a \u0639\u0646 \u062a\u0642\u0627\u0631\u064a\u0631 \u0643\u062b\u064a\u0631\u0629.","\u0623\u0637\u064a\u0628 \u0627\u0644\u0632\u064a\u0627\u0631\u0627\u062a \u0645\u0627 \u0643\u0627\u0646\u062a \u062a\u0634\u062c\u064a\u0639\u064b\u0627 \u0642\u0628\u0644 \u0623\u0646 \u062a\u0643\u0648\u0646 \u062a\u0642\u064a\u064a\u0645\u064b\u0627.","\u0633\u0624\u0627\u0644\u064c \u0644\u0637\u064a\u0641 \u0644\u0644\u0637\u0627\u0644\u0628 \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u0632\u064a\u0627\u0631\u0629 \u064a\u0634\u062c\u0651\u0639\u0647 \u0623\u0643\u062b\u0631 \u0645\u0646 \u0623\u064a\u0651 \u062a\u0642\u0631\u064a\u0631.","\u0645\u0639\u0644\u0651\u0645\u064c \u064a\u064f\u0634\u0643\u0631 \u0623\u0645\u0627\u0645 \u0637\u0644\u0627\u0628\u0647 \u064a\u0632\u062f\u0627\u062f \u0647\u0645\u0651\u0629\u061b \u0648\u0641\u0651\u0642\u0643 \u0627\u0644\u0644\u0647."],t.s)
B.bUA=s(["\u0637\u0644\u0627\u0628\u0643 \u0639\u0644\u0649 \u0645\u0648\u0639\u062f\u064d \u0645\u0639\u0643 \u0641\u064a \u0627\u0644\u062d\u0644\u0642\u0629\u061b \u064a\u0633\u0651\u0631 \u0627\u0644\u0644\u0647 \u0644\u0643\u0645.","\u0648\u0642\u062a \u0627\u0644\u062d\u0644\u0642\u0629\u061b \u064a\u0633\u0651\u0631 \u0627\u0644\u0644\u0647 \u0644\u0643 \u0648\u0644\u0637\u0644\u0627\u0628\u0643.","\u0643\u0644\u0645\u0629\u064c \u0637\u064a\u0651\u0628\u0629 \u0644\u0637\u0627\u0644\u0628\u064d \u0645\u062a\u0639\u062b\u0651\u0631 \u0642\u062f \u062a\u063a\u064a\u0651\u0631 \u064a\u0648\u0645\u0647 \u0643\u0644\u0651\u0647.","\u0635\u0628\u0631\u064c \u0639\u0644\u0649 \u0627\u0644\u0637\u0627\u0644\u0628 \u0627\u0644\u0628\u0637\u064a\u0621 \u0627\u0644\u064a\u0648\u0645 \u062b\u0645\u0631\u062a\u0647 \u062d\u0627\u0641\u0638\u064c \u0645\u062a\u0642\u0646 \u063a\u062f\u064b\u0627.","\u0627\u0628\u062a\u0633\u0627\u0645\u0629\u064c \u0641\u064a \u0648\u062c\u0647 \u0627\u0644\u0637\u0627\u0644\u0628 \u0635\u062f\u0642\u0629\u060c \u0648\u062a\u0641\u062a\u062d \u0642\u0644\u0628\u0647 \u0644\u0644\u062d\u0641\u0638."],t.s)
B.bTl=s(["\u064a\u0633\u0651\u0631 \u0627\u0644\u0644\u0647 \u0645\u062c\u0627\u0644\u0633 \u0627\u0644\u064a\u0648\u0645 \u0648\u0628\u0627\u0631\u0643 \u0641\u064a\u0647\u0627.","\u0648\u0642\u062a \u0627\u0644\u0625\u0642\u0631\u0627\u0621\u061b \u0628\u0627\u0631\u0643 \u0627\u0644\u0644\u0647 \u0641\u064a \u0627\u0644\u0645\u062c\u0644\u0633.","\u0627\u0644\u062a\u0644\u0627\u0648\u0629 \u0627\u0644\u0645\u062a\u0642\u0646\u0629 \u062a\u0628\u062f\u0623 \u0645\u0646 \u0645\u062c\u0644\u0633\u064d \u0647\u0627\u062f\u0626\u061b \u0623\u0639\u0627\u0646\u0643 \u0627\u0644\u0644\u0647.","\u062a\u0635\u062d\u064a\u062d\u064c \u0628\u0631\u0641\u0642\u064d \u064a\u0628\u0642\u0649 \u0623\u062b\u0631\u0647 \u0623\u0637\u0648\u0644\u061b \u0628\u0627\u0631\u0643 \u0627\u0644\u0644\u0647 \u0641\u064a \u0627\u0644\u0645\u062c\u0644\u0633.","\u0643\u0644 \u0642\u0627\u0631\u0626\u064d \u064a\u064f\u062a\u0642\u0646 \u0627\u0644\u064a\u0648\u0645 \u062d\u0644\u0642\u0629\u064c \u062c\u062f\u064a\u062f\u0629 \u0641\u064a \u0627\u0644\u0633\u0646\u062f."],t.s)
B.b3x=s(["\u064a\u0633\u0651\u0631 \u0627\u0644\u0644\u0647 \u0644\u062c\u0646\u0629 \u0627\u0644\u064a\u0648\u0645\u060c \u0648\u062b\u0628\u0651\u062a \u0627\u0644\u062d\u0641\u0638\u0629.","\u0643\u0644\u0645\u0629\u064c \u0645\u0637\u0645\u0626\u0646\u0629 \u0642\u0628\u0644 \u0627\u0644\u0627\u062e\u062a\u0628\u0627\u0631 \u062a\u064f\u062e\u0631\u062c \u0645\u0646 \u0627\u0644\u0637\u0627\u0644\u0628 \u0623\u062d\u0633\u0646 \u0645\u0627 \u0639\u0646\u062f\u0647.","\u0648\u0642\u062a \u0627\u0644\u0644\u062c\u0646\u0629\u061b \u0623\u0639\u0627\u0646\u0643 \u0627\u0644\u0644\u0647 \u0639\u0644\u0649 \u0627\u0644\u0639\u062f\u0644 \u0648\u0627\u0644\u0631\u0641\u0642.","\u0627\u0644\u0631\u0641\u0642 \u0628\u0627\u0644\u062d\u0627\u0641\u0638 \u0627\u0644\u0645\u0631\u062a\u0628\u0643 \u064a\u064f\u0638\u0647\u0631 \u062d\u0641\u0638\u0647 \u0627\u0644\u062d\u0642\u064a\u0642\u064a\u0651.","\u062a\u0642\u062f\u064a\u0631\u064c \u0645\u0646\u0635\u0641 \u0627\u0644\u064a\u0648\u0645 \u062f\u0627\u0641\u0639\u064c \u0644\u0644\u062d\u0627\u0641\u0638 \u0625\u0644\u0649 \u0645\u0627 \u0628\u0639\u062f\u0647."],t.s)
B.c8V=new A.c5([B.lO,B.bV0,B.lP,B.bDK,B.k2,B.bUA,B.mS,B.bTl,B.mT,B.b3x],t.lZ)
B.c4g=s(["\u0645\u0627 \u064a\u064f\u062f\u062e\u064e\u0644 \u0645\u0646 \u0646\u0634\u0627\u0637 \u0627\u0644\u064a\u0648\u0645 \u0645\u062d\u0641\u0648\u0638\u061b \u0634\u0643\u0631 \u0627\u0644\u0644\u0647 \u0633\u0639\u064a\u0643.","\u064a\u0648\u0645\u064c \u0639\u0627\u0645\u0631 \u0628\u0627\u0644\u062d\u0644\u0642\u0627\u062a\u060c \u0648\u0645\u0627 \u0628\u0642\u064a \u064a\u0645\u0643\u0646 \u0623\u0646 \u064a\u0646\u062a\u0638\u0631 \u0627\u0644\u063a\u062f.","\u064a\u0648\u0645\u064c \u0622\u062e\u0631 \u0641\u064a \u062e\u062f\u0645\u0629 \u0627\u0644\u0642\u0631\u0622\u0646\u061b \u062a\u0642\u0628\u0651\u0644 \u0627\u0644\u0644\u0647 \u0645\u0646\u0643.","\u062d\u0635\u0627\u062f \u0627\u0644\u0634\u0647\u0631 \u062d\u062a\u0649 \u0627\u0644\u064a\u0648\u0645 \u062a\u062c\u062f\u0647 \u0641\u064a \u0627\u0644\u0623\u0631\u0642\u0627\u0645 \u0623\u0639\u0644\u0649 \u0627\u0644\u0635\u0641\u062d\u0629.","\u0645\u0627 \u0623\u064f\u0646\u062c\u0632 \u0627\u0644\u064a\u0648\u0645 \u0641\u064a \u0627\u0644\u0645\u0631\u0627\u0643\u0632 \u062b\u0645\u0631\u0629 \u0641\u0631\u064a\u0642\u064d \u0643\u0627\u0645\u0644\u061b \u0634\u0643\u0631 \u0627\u0644\u0644\u0647 \u0644\u0644\u062c\u0645\u064a\u0639."],t.s)
B.c39=s(["\u062a\u0642\u0627\u0631\u064a\u0631 \u0632\u064a\u0627\u0631\u0627\u062a \u0627\u0644\u064a\u0648\u0645: \u0645\u0627 \u0628\u0642\u064a \u0645\u0646\u0647\u0627 \u062a\u062c\u062f\u0647 \u0623\u0633\u0641\u0644 \u0627\u0644\u0635\u0641\u062d\u0629.","\u0634\u0643\u0631 \u0627\u0644\u0644\u0647 \u0633\u0639\u064a\u0643 \u0641\u064a \u0645\u062a\u0627\u0628\u0639\u0629 \u0627\u0644\u062d\u0644\u0642\u0627\u062a \u0627\u0644\u064a\u0648\u0645.","\u064a\u0648\u0645\u064c \u0645\u0646 \u0627\u0644\u0645\u062a\u0627\u0628\u0639\u0629 \u0645\u0636\u0649 \u0628\u062e\u064a\u0631\u061b \u062a\u0642\u0628\u0651\u0644 \u0627\u0644\u0644\u0647 \u0645\u0646\u0643.","\u062a\u0642\u0631\u064a\u0631\u064c \u064a\u064f\u0643\u062a\u0628 \u0627\u0644\u0644\u064a\u0644\u0629 \u0623\u062f\u0642\u0651 \u0645\u0646 \u062a\u0642\u0631\u064a\u0631\u064d \u064a\u064f\u0643\u062a\u0628 \u0628\u0639\u062f \u0623\u064a\u0627\u0645.","\u0634\u0643\u0631\u064c \u0644\u0645\u0639\u0644\u0651\u0645\u064d \u0632\u0631\u062a\u0647 \u0627\u0644\u064a\u0648\u0645 \u064a\u0628\u0642\u0649 \u0623\u062b\u0631\u0647 \u0637\u0648\u064a\u0644\u064b\u0627."],t.s)
B.bUT=s(["\u0646\u0634\u0627\u0637 \u0627\u0644\u064a\u0648\u0645: \u0625\u0646 \u0628\u0642\u064a \u0645\u0646\u0647 \u0634\u064a\u0621\u064c \u0644\u0645 \u064a\u064f\u062f\u062e\u064e\u0644 \u062a\u062c\u062f\u0647 \u0647\u0646\u0627.","\u062d\u0644\u0642\u0629 \u0627\u0644\u064a\u0648\u0645 \u0641\u064a \u0645\u064a\u0632\u0627\u0646\u0643 \u0628\u0625\u0630\u0646 \u0627\u0644\u0644\u0647\u061b \u062a\u0642\u0628\u0651\u0644 \u0627\u0644\u0644\u0647 \u0645\u0646\u0643.","\u0645\u0627 \u062d\u0641\u0638\u0647 \u0637\u0644\u0627\u0628\u0643 \u0627\u0644\u064a\u0648\u0645 \u0635\u062f\u0642\u0629\u064c \u062c\u0627\u0631\u064a\u0629 \u0644\u0643 \u0628\u0625\u0630\u0646 \u0627\u0644\u0644\u0647.","\u062a\u0639\u0628\u064f \u0627\u0644\u064a\u0648\u0645 \u0641\u064a \u0627\u0644\u062d\u0644\u0642\u0629 \u0623\u062c\u0631\u064c \u0645\u062f\u0651\u062e\u0631 \u0628\u0625\u0630\u0646 \u0627\u0644\u0644\u0647.","\u0645\u0627 \u0623\u064f\u062f\u062e\u0644 \u0645\u0646 \u0646\u0634\u0627\u0637 \u0627\u0644\u064a\u0648\u0645 \u064a\u062d\u0641\u0638 \u0644\u0643\u0644 \u0637\u0627\u0644\u0628\u064d \u0645\u0633\u064a\u0631\u062a\u0647."],t.s)
B.bQZ=s(["\u062a\u0642\u0628\u0651\u0644 \u0627\u0644\u0644\u0647 \u0645\u062c\u0627\u0644\u0633 \u0627\u0644\u064a\u0648\u0645.","\u062a\u0644\u0627\u0648\u0627\u062a \u0627\u0644\u064a\u0648\u0645: \u0645\u0627 \u0628\u0642\u064a \u0645\u0646\u0647\u0627 \u062a\u062c\u062f\u0647 \u0647\u0646\u0627.","\u0645\u062c\u0644\u0633\u064c \u0622\u062e\u0631 \u0641\u064a \u062d\u0641\u0638 \u0627\u0644\u0633\u0646\u062f\u061b \u0628\u0627\u0631\u0643 \u0627\u0644\u0644\u0647 \u0641\u064a\u0643.","\u0645\u0627 \u0636\u064f\u0628\u0637 \u0627\u0644\u064a\u0648\u0645 \u0645\u0646 \u062d\u0631\u0648\u0641\u064d \u064a\u0628\u0642\u0649 \u0641\u064a \u0635\u062f\u0648\u0631 \u0627\u0644\u0642\u0627\u0631\u0626\u064a\u0646.","\u062a\u0642\u0628\u0651\u0644 \u0627\u0644\u0644\u0647 \u0627\u0644\u062a\u0644\u0627\u0648\u0629 \u0648\u0627\u0644\u062a\u0635\u062d\u064a\u062d\u061b \u0645\u0633\u0627\u0621\u064c \u0645\u0628\u0627\u0631\u0643."],t.s)
B.bQx=s(["\u0645\u0627 \u0631\u0635\u062f\u062a\u064e\u0647 \u0627\u0644\u064a\u0648\u0645 \u064a\u0635\u0644 \u0625\u0644\u0649 \u0623\u0635\u062d\u0627\u0628\u0647\u061b \u0634\u0643\u0631 \u0627\u0644\u0644\u0647 \u0633\u0639\u064a\u0643.","\u0625\u0646 \u0628\u0642\u064a \u0637\u0627\u0644\u0628\u064c \u0644\u0645 \u062a\u064f\u0631\u0635\u062f \u0646\u062a\u064a\u062c\u062a\u0647 \u062a\u062c\u062f\u0647 \u0641\u064a \xab\u0644\u062c\u0646\u062a\u064a \u0627\u0644\u064a\u0648\u0645\xbb.","\u064a\u0648\u0645\u064c \u0622\u062e\u0631 \u0641\u064a \u062e\u062f\u0645\u0629 \u0627\u0644\u062d\u0641\u0638\u0629\u061b \u062a\u0642\u0628\u0651\u0644 \u0627\u0644\u0644\u0647 \u0645\u0646\u0643.","\u0646\u062a\u064a\u062c\u0629\u064c \u062a\u064f\u0631\u0635\u062f \u0627\u0644\u064a\u0648\u0645 \u0641\u0631\u062d\u0629\u064c \u062a\u0635\u0644 \u0625\u0644\u0649 \u0628\u064a\u062a\u064d \u0627\u0644\u0644\u064a\u0644\u0629.","\u062a\u0642\u0628\u0651\u0644 \u0627\u0644\u0644\u0647 \u062c\u0647\u062f \u0627\u0644\u0644\u062c\u0646\u0629\u061b \u0645\u0633\u0627\u0621\u064c \u0645\u0628\u0627\u0631\u0643."],t.s)
B.c8X=new A.c5([B.lO,B.c4g,B.lP,B.c39,B.k2,B.bUT,B.mS,B.bQZ,B.mT,B.bQx],t.lZ)
B.bVx=s(["\u062a\u0623\u062e\u0651\u0631 \u0627\u0644\u0648\u0642\u062a\u061b \u0631\u0627\u062d\u062a\u0643 \u062c\u0632\u0621\u064c \u0645\u0646 \u0627\u0644\u0639\u0645\u0644\u060c \u0648\u0627\u0644\u063a\u062f \u064a\u062d\u062a\u0627\u062c\u0643.","\u0639\u0645\u0644\u064c \u0641\u064a \u0633\u0627\u0639\u0629\u064d \u0645\u062a\u0623\u062e\u0651\u0631\u0629\u061b \u0623\u0639\u0627\u0646\u0643 \u0627\u0644\u0644\u0647.","\u0645\u0627 \u0628\u0642\u064a \u064a\u064f\u0643\u0645\u064e\u0644 \u063a\u062f\u064b\u0627 \u0628\u0625\u0630\u0646 \u0627\u0644\u0644\u0647\u061b \u0644\u064a\u0644\u0629\u064c \u0647\u0627\u0646\u0626\u0629.","\u0623\u0639\u0627\u0646\u0643 \u0627\u0644\u0644\u0647 \u0639\u0644\u0649 \u0645\u0627 \u062a\u062d\u0645\u0644\u061b \u0644\u064a\u0644\u0629\u064c \u0647\u0627\u0646\u0626\u0629.","\u0645\u0627 \u0644\u0645 \u064a\u0643\u062a\u0645\u0644 \u0627\u0644\u064a\u0648\u0645 \u064a\u0646\u062a\u0638\u0631 \u0635\u0628\u0627\u062d\u064b\u0627 \u0645\u0628\u0627\u0631\u0643\u064b\u0627."],t.s)
B.bHd=s(["\u062a\u0623\u062e\u0651\u0631 \u0627\u0644\u0648\u0642\u062a\u061b \u0631\u0627\u062d\u062a\u0643 \u062c\u0632\u0621\u064c \u0645\u0646 \u0627\u0644\u0639\u0645\u0644.","\u0623\u0639\u0627\u0646\u0643 \u0627\u0644\u0644\u0647\u061b \u0645\u0627 \u0628\u0642\u064a \u064a\u064f\u0643\u0645\u064e\u0644 \u063a\u062f\u064b\u0627.","\u0644\u064a\u0644\u0629\u064c \u0647\u0627\u0646\u0626\u0629\u060c \u0648\u063a\u062f\u064c \u0645\u0628\u0627\u0631\u0643 \u0628\u0625\u0630\u0646 \u0627\u0644\u0644\u0647.","\u0632\u064a\u0627\u0631\u0627\u062a \u0627\u0644\u063a\u062f \u062a\u0628\u062f\u0623 \u0628\u0646\u0648\u0645\u064d \u0647\u0627\u0646\u0626 \u0627\u0644\u0644\u064a\u0644\u0629.","\u062a\u0642\u0628\u0651\u0644 \u0627\u0644\u0644\u0647 \u0645\u062a\u0627\u0628\u0639\u0629 \u0627\u0644\u064a\u0648\u0645\u061b \u0644\u064a\u0644\u0629\u064c \u0647\u0627\u0646\u0626\u0629."],t.s)
